int led = 13;

void setup() {
    pinMode(led, OUTPUT); // Configura el pin 13 como salida
}

void loop() {
    // Repite la secuencia de parpadeo exactamente 5 veces
    for (int i = 0; i < 5; i++) {
        digitalWrite(led, HIGH);
        delay(500);
        digitalWrite(led, LOW);
        delay(500);
    }

    // Espera 3 segundos antes de iniciar el próximo ciclo del loop()
    delay(3000);
}
